//! The aarch64 sendsig frame checked against the S160 donor table.
//!
//! `tests/abi/signal-frame/donor-layout.txt` now carries the aarch64 rows generated by
//! `tests/abi/signal-frame/donor-layout.c` (NetBSD `__gregs[35]`/`__fregs`/`__spare[8]` in the
//! C19/S160 ucontext order). This test parses every aarch64 row and asserts the kernel's
//! `signal.rs` layout against it.

use super::*;

use core::mem::{offset_of, size_of};

fn parse_hex(text: &str) -> usize {
    usize::from_str_radix(text.trim_start_matches("0x"), 16).expect("hex value")
}

fn donor_table() -> std::collections::HashMap<String, usize> {
    let mut found = None;
    for dir in std::path::Path::new(env!("CARGO_MANIFEST_DIR")).ancestors() {
        let candidate = dir.join("tests/abi/signal-frame/donor-layout.txt");
        if candidate.is_file() {
            found = Some(candidate);
            break;
        }
    }
    let path = found.expect("tests/abi/signal-frame/donor-layout.txt");
    let text = std::fs::read_to_string(path).expect("donor layout");
    let mut rows = std::collections::HashMap::new();
    for line in text.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        if let Some(rest) = line.strip_prefix("sizeof(") {
            let (name, rest) = rest.split_once(")=").expect("sizeof row");
            let (size, _align) = rest.split_once(" align=").expect("sizeof align");
            rows.insert(format!("sizeof({name})"), parse_hex(size));
        } else if let Some((name, value)) = line.split_once('=') {
            let value = if name.starts_with("aarch64_reg_") {
                value.parse::<usize>().expect("aarch64 reg index")
            } else {
                parse_hex(value)
            };
            rows.insert(name.to_string(), value);
        }
    }
    rows
}

#[test]
fn aarch64_frame_matches_the_s160_donor_table() {
    let table = donor_table();
    let value = |name: &str| {
        *table
            .get(name)
            .unwrap_or_else(|| panic!("{name} missing from the S160 donor table"))
    };

    assert_eq!(
        SIGINFO_SIZE,
        value("sizeof(aarch64_siginfo_t)"),
        "sizeof(aarch64_siginfo_t)"
    );
    assert_eq!(
        size_of::<[u32; 4]>(),
        value("sizeof(aarch64_sigset_t)"),
        "sizeof(aarch64_sigset_t)"
    );
    assert_eq!(
        FREGSET_SIZE,
        value("sizeof(aarch64_fregset_t)"),
        "sizeof(aarch64_fregset_t)"
    );
    assert_eq!(
        offset_of!(FpregsetLayout, q),
        value("aarch64_fregset_t.__qregs"),
        "aarch64_fregset_t.__qregs"
    );
    assert_eq!(
        offset_of!(FpregsetLayout, fpcr),
        value("aarch64_fregset_t.__fpcr"),
        "aarch64_fregset_t.__fpcr"
    );
    assert_eq!(
        offset_of!(FpregsetLayout, fpsr),
        value("aarch64_fregset_t.__fpsr"),
        "aarch64_fregset_t.__fpsr"
    );
    assert_eq!(
        MCONTEXT_SIZE,
        value("sizeof(aarch64_mcontext_t)"),
        "sizeof(aarch64_mcontext_t)"
    );
    assert_eq!(
        MC_GREGS_OFFSET,
        value("aarch64_mcontext_t.__gregs"),
        "aarch64_mcontext_t.__gregs"
    );
    assert_eq!(
        MC_FREGS_OFFSET,
        value("aarch64_mcontext_t.__fregs"),
        "aarch64_mcontext_t.__fregs"
    );
    assert_eq!(
        MC_SPARE_OFFSET,
        value("aarch64_mcontext_t.__spare"),
        "aarch64_mcontext_t.__spare"
    );
    assert_eq!(
        size_of::<StackLayout>(),
        value("sizeof(aarch64_stack_t)"),
        "sizeof(aarch64_stack_t)"
    );
    assert_eq!(
        offset_of!(StackLayout, ss_sp),
        value("aarch64_stack_t.ss_sp"),
        "aarch64_stack_t.ss_sp"
    );
    assert_eq!(
        offset_of!(StackLayout, ss_size),
        value("aarch64_stack_t.ss_size"),
        "aarch64_stack_t.ss_size"
    );
    assert_eq!(
        offset_of!(StackLayout, ss_flags),
        value("aarch64_stack_t.ss_flags"),
        "aarch64_stack_t.ss_flags"
    );
    assert_eq!(
        UCONTEXT_SIZE,
        value("sizeof(aarch64_ucontext_t)"),
        "sizeof(aarch64_ucontext_t)"
    );
    assert_eq!(
        UC_SIGMASK_OFFSET,
        value("aarch64_ucontext_t.uc_sigmask"),
        "aarch64_ucontext_t.uc_sigmask"
    );
    assert_eq!(
        UC_MCONTEXT_OFFSET,
        value("aarch64_ucontext_t.uc_mcontext"),
        "aarch64_ucontext_t.uc_mcontext"
    );
    assert_eq!(
        UC_LINK_OFFSET,
        value("aarch64_ucontext_t.uc_link"),
        "aarch64_ucontext_t.uc_link"
    );
    assert_eq!(
        UC_STACK_OFFSET,
        value("aarch64_ucontext_t.uc_stack"),
        "aarch64_ucontext_t.uc_stack"
    );
    assert_eq!(
        UC_FLAGS_OFFSET,
        value("aarch64_ucontext_t.uc_flags"),
        "aarch64_ucontext_t.uc_flags"
    );
    assert_eq!(
        offset_of!(UContextLayout, uc_spare),
        value("aarch64_ucontext_t.__spare__"),
        "aarch64_ucontext_t.__spare__"
    );
    assert_eq!(REG_X0, value("aarch64_reg_X0"), "aarch64_reg_X0");
    assert_eq!(REG_X30, value("aarch64_reg_X30"), "aarch64_reg_X30");
    assert_eq!(REG_SP, value("aarch64_reg_SP"), "aarch64_reg_SP");
    assert_eq!(REG_ELR, value("aarch64_reg_ELR"), "aarch64_reg_ELR");
    assert_eq!(REG_SPSR, value("aarch64_reg_SPSR"), "aarch64_reg_SPSR");
    assert_eq!(REG_TPIDR, value("aarch64_reg_TPIDR"), "aarch64_reg_TPIDR");
    assert_eq!(NGREG, 35);
    assert_eq!(NFREG, 32);
}
